function strategy_separated_users(array$ids):void{$ids=array_values(array_filter(array_map('intval',$ids)));if(count($ids)!==count(array_unique($ids)))throw new RuntimeException('Preparation, review, approval, execution, and benefit validation must remain separated.');foreach($ids as$id)if(!executive_intelligence_active_user($id))throw new RuntimeException('Governance assignments require active visible users.');}
