function strategy_save_portfolio(array$record):array{$existing=!empty($record['id'])?strategy_find_portfolio((int)$record['id']):null;if($existing&&(($existing['status']??'')==='published'||!empty($existing['locked_at']))){foreach(['portfolio_number','portfolio_name','portfolio_type','entity_id','company_id','fiscal_year','funding_limit','capacity_limit_hours','strategic_theme','owner_user_id','reviewer_user_id','approver_user_id']as$field)if((string)($existing[$field]??'')!==(string)($record[$field]??''))throw new RuntimeException('Published portfolios are immutable; create a new fiscal portfolio.');}$entity=!empty($record['entity_id'])?(int)$record['entity_id']:null;if(!strategy_portfolio_visible_entity($entity))throw new RuntimeException('Portfolio entity is outside the active scope.');strategy_separated_users([(int)$record['owner_user_id'],(int)$record['reviewer_user_id'],(int)$record['approver_user_id']]);if(trim((string)$record['portfolio_name'])===''||trim((string)$record['strategic_theme'])==='')throw new RuntimeException('Portfolio name, strategic theme, and evidence are required.');$record['company_id']=$entity?executive_intelligence_company_id($entity):null;$record['funding_limit']=max(0,(float)$record['funding_limit']);$record['capacity_limit_hours']=max(0,(float)$record['capacity_limit_hours']);return strategy_portfolio_save_row('enterprise_strategy_portfolios','enterprise_strategy_portfolios','strategy_portfolio_demo_portfolios',$record,['portfolio_number','portfolio_name','portfolio_type','entity_id','company_id','fiscal_year','funding_limit','capacity_limit_hours','strategic_theme','status','owner_user_id','reviewer_user_id','approver_user_id','evidence_note','published_at','locked_at','created_by']);}
function strategy_publish_portfolio(int$id,string$note):array{require_permission('portfolio_intelligence.approve');$row=strategy_find_portfolio($id);if(!$row||($row['status']??'')!=='reviewed')throw new RuntimeException('Portfolio requires independent review before publication.');if((int)$row['approver_user_id']!==(int)current_user()['id'])throw new RuntimeException('Only the assigned independent approver may publish this portfolio.');if(trim($note)==='')throw new RuntimeException('Portfolio approval evidence is required.');$row['status']='published';$row['evidence_note']=trim($row['evidence_note']).' Approval: '.mb_substr(trim($note),0,3000);$row['published_at']=date('Y-m-d H:i:s');$row['locked_at']=$row['published_at'];return strategy_save_portfolio($row);}
