function strategy_prepare_gate(int$initiativeId,string$toStage,string$evidence):array{require_permission('portfolio_intelligence.submit');$initiative=strategy_find_initiative($initiativeId);if(!$initiative)throw new RuntimeException('Initiative is outside the active scope.');$allowed=['idea'=>'business_case','business_case'=>'reviewed','reviewed'=>'approved','approved'=>'funded','funded'=>'in_execution','in_execution'=>'benefits_validation','benefits_validation'=>'completed'];$from=(string)$initiative['stage'];if(($allowed[$from]??null)!==$toStage)throw new RuntimeException('Invalid initiative stage-gate transition.');$key=hash('sha256',$initiativeId.'|'.$from.'|'.$toStage);foreach(strategy_stage_gates($initiativeId)as$gate)if(hash_equals((string)$gate['idempotency_key'],$key))return$gate;return strategy_portfolio_save_row('enterprise_initiative_stage_gates','enterprise_initiative_stage_gates','strategy_portfolio_demo_gates',['id'=>null,'initiative_id'=>$initiativeId,'gate_code'=>strtoupper($from.'-TO-'.$toStage),'from_stage'=>$from,'to_stage'=>$toStage,'status'=>'prepared','decision'=>null,'prepared_by'=>(int)current_user()['id'],'reviewed_by'=>(int)$initiative['reviewer_user_id'],'approved_by'=>(int)$initiative['approver_user_id'],'evidence_note'=>mb_substr(trim($evidence),0,5000),'review_note'=>'','approval_note'=>'','idempotency_key'=>$key,'prepared_at'=>date('Y-m-d H:i:s'),'reviewed_at'=>null,'approved_at'=>null,'locked_at'=>null],['initiative_id','gate_code','from_stage','to_stage','status','decision','prepared_by','reviewed_by','approved_by','evidence_note','review_note','approval_note','idempotency_key','prepared_at','reviewed_at','approved_at','locked_at']);}
