function strategy_generate_scenario(int$portfolioId,string$type,float$budgetLimit,float$capacityLimit,int$reviewerId,string$note):array{require_permission('portfolio_intelligence.create');$portfolio=strategy_find_portfolio($portfolioId);if(!$portfolio)throw new RuntimeException('Portfolio is outside the active scope.');if((int)current_user()['id']===$reviewerId)throw new RuntimeException('Scenario preparation and review must remain separate.');$weights=match($type){'risk_reduction'=>['alignment'=>.2,'value'=>.15,'urgency'=>.2,'risk'=>.45],'savings_priority'=>['alignment'=>.2,'value'=>.5,'urgency'=>.2,'risk'=>.1],'process_automation'=>['alignment'=>.35,'value'=>.3,'urgency'=>.2,'risk'=>.15],default=>['alignment'=>.35,'value'=>.3,'urgency'=>.2,'risk'=>.15]};$candidates=[];foreach(strategy_initiatives($portfolioId)as$row){if(in_array($row['stage'],['completed','cancelled'],true))continue;$score=round($row['strategic_alignment_score']*$weights['alignment']+$row['value_score']*$weights['value']+$row['urgency_score']*$weights['urgency']+$row['risk_score']*$weights['risk'],2);$candidates[]=['initiative_id'=>$row['id'],'initiative_number'=>$row['initiative_number'],'name'=>$row['initiative_name'],'score'=>$score,'cost'=>(float)$row['forecast_cost'],'benefit'=>(float)$row['expected_annual_benefit'],'capacity'=>(float)$row['capacity_demand_hours'],'selected'=>false];}usort($candidates,static fn(array$a,array$b):int=>$b['score']<=>$a['score']);$cost=0.0;$benefit=0.0;$capacity=0.0;foreach($candidates as$i=>$row){if(($budgetLimit>0&&$cost+$row['cost']>$budgetLimit)||($capacityLimit>0&&$capacity+$row['capacity']>$capacityLimit))continue;$candidates[$i]['selected']=true;$cost+=$row['cost'];$benefit+=$row['benefit'];$capacity+=$row['capacity'];}$key=hash('sha256',$portfolioId.'|'.$type.'|'.number_format($budgetLimit,2,'.','').'|'.number_format($capacityLimit,2,'.',''));foreach(strategy_scenarios($portfolioId)as$row)if(hash_equals((string)$row['idempotency_key'],$key))return$row;ret