function strategy_agent_extend_workspace(array$workspace):array{$metrics=strategy_metrics();$risk=array_values(array_filter(strategy_initiatives(),static fn(array$row):bool=>in_array(strategy_portfolio_health($row),['warning','critical'],true)));usort($risk,static fn(array$a,array$b):int=>(strategy_portfolio_health($a)==='critical'?0:1)<=>(strategy_portfolio_health($b)==='critical'?0:1));$rows=[];foreach(array_slice($risk,0,5)as$row)$rows[]='<li><strong>'.h($row['initiative_name']).'</strong> · '.h(status_label(strategy_portfolio_health($row))).' · '.money((float)$row['forecast_cost']).' forecast · '.money((float)$row['expected_annual_benefit']).' expected benefit</li>';if(!$rows)$rows[]='<li>No active initiatives currently require escalation.</li>';$prompt=['icon'=>'◆','title'=>'Strategy portfolio','description'=>'Trace goals and KPI gaps into initiatives, process impact, funding, capacity, milestones, and validated benefits.','prompt'=>'Which initiatives should leadership fund, pause, or review, and what goal, KPI, process, capacity, financial, and benefit evidence supports that recommendation?','keywords'=>['portfolio','initiative','strategy','funding','benefit','transformation','business case','stage gate'],'response_title'=>'Strategy Portfolio Agent','response_html'=>'<p><strong>'.$metrics['initiatives'].' initiatives · '.$metrics['at_risk'].' at risk · '.money($metrics['approved_funding']).' approved funding · '.money($metrics['validated_benefit']).' validated benefits.</strong></p><ul>'.implode('',$rows).'</ul><p>Recommendations are advisory. Funding, stage-gate approvals, process publication, and benefits validation remain human-governed.</p><a class="agent-inline-link" href="'.h(app_url('strategy-portfolio.php')).'">Open Strategy Portfolio →</a>','evidence'=>[$metrics['active'].' active initiatives',$metrics['open_milestones'].' open milestones',$metrics['process_changes'].' process-change proposals',money($metrics['expected_benefit']).' expected annual ben